{
  "name": "tube-room",
  "version": "1.1.0",
  "private": true,
  "type": "module",
  "description": "Five-tube audio-reactive WLED controller. No npm dependencies.",
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "start": "node runner.mjs",
    "test": "node --test test/*.test.mjs",
    "build:update": "node scripts/build-update.mjs"
  }
}

import http from 'node:http';
import dgram from 'node:dgram';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import crypto from 'node:crypto';
import {LIMIT,updaterInfo,setSource,fetchUpdate,installBundle,rollback} from './updater.mjs';
import {Engine,defaults,cleanConfig,clamp,ddpPackets,effects} from './engine.mjs';
const ROOT=path.dirname(fileURLToPath(import.meta.url));
const PACKAGE=JSON.parse(fs.readFileSync(path.join(ROOT,'package.json'),'utf8')),VERSION=PACKAGE.version;
let pendingUpdate=null,restarting=false;
const PORT=Number(process.env.TUBEROOM_PORT||8788),HOST='127.0.0.1';
const DATA=process.env.TUBEROOM_DATA||path.join(os.homedir(), 'Library','Application Support','TubeRoom');
fs.mkdirSync(DATA,{recursive:true});
if(PACKAGE.updateSource&&!fs.existsSync(path.join(DATA,'update-source.json')))setSource(DATA,PACKAGE.updateSource);
let config=defaults();try{config=cleanConfig(JSON.parse(fs.readFileSync(path.join(DATA,'settings.json'),'utf8')));}catch{}
let saveTimer;const save=()=>{clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{fs.writeFileSync(path.join(DATA,'settings.tmp'),JSON.stringify(config,null,2));fs.renameSync(path.join(DATA,'settings.tmp'),path.join(DATA,'settings.json'));}catch(e){status.error='Could not save settings: '+e.message;}},200);};
const token=crypto.randomBytes(24).toString('hex'),engine=new Engine(),udp=dgram.createSocket('udp4');
const clients=new Set(),snapshots=new Map(),status={live:false,busy:false,error:'',devices:{},sent:0,lastSend:0,source:'none',audioAge:null};
let sessionOwner='',lastHeartbeat=0,input={level:0,bass:0,mid:0,high:0,beat:false},lastAudio=0,seq=0,tick=0,identifying=false;
udp.on('error',e=>{status.error='Lighting network: '+e.message;});
const privateIP=ip=>/^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(ip)&&ip.split('.').length===4&&ip.split('.').every(p=>/^\d{1,3}$/.test(p)&&+p<=255);
const validIP=ip=>privateIP(ip)||(process.env.TUBEROOM_TEST==='1'&&ip==='127.0.0.1');
function validateTubes(c){const ips=new Set();for(const t of c.tubes){if(t.ip&&!validIP(t.ip))throw Error(`${t.name}: use the local IPv4 address shown in WLED, e.g. 192.168.1.101.`);if(t.ip&&ips.has(t.ip))throw Error('Two tube slots have the same IP address.');if(t.ip)ips.add(t.ip);}}
async function wled(ip,route='/json/info',body,timeout=1800){
 if(!validIP(ip))throw Error('Enter a local IPv4 address.');
 const testPort=process.env.TUBEROOM_TEST==='1'&&process.env.TUBEROOM_WLED_PORT?':'+process.env.TUBEROOM_WLED_PORT:'';
 const response=await fetch(`http://${ip}${testPort}${route}`,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(timeout)});
 if(!response.ok)throw Error('WLED returned HTTP '+response.status);return response.json();
}
function infoValid(info){return info&&Number.isInteger(info.leds?.count)&&info.leds.count>0&&typeof info.ver==='string';}
async function probe(t){try{const info=await wled(t.ip);if(!infoValid(info))throw Error('This address did not return WLED device information.');const d={ok:true,ip:t.ip,name:String(info.name||'WLED'),count:info.leds.count,version:info.ver,signal:info.wifi?.signal,receiving:!!info.live,checked:Date.now()};status.devices[t.id]=d;return d;}catch(e){return status.devices[t.id]={ok:false,ip:t.ip,error:e.message,checked:Date.now()};}}
function sendFrame(t,frame){if(!t.ip||!t.enabled)return;for(const packet of ddpPackets(frame,seq))udp.send(packet,4048,t.ip,e=>{if(e)status.error=`${t.name}: ${e.message}`;});status.sent++;status.lastSend=Date.now();}
function restorePayload(s){const p={...s,live:false,lor:s.lor??0,transition:s.transition??0,udpn:{...s.udpn,nn:true}};for(const k of ['ps','pl','time','tb','nl','u'])delete p[k];return p;}
async function restoreAll(forceOff=false){const entries=[...snapshots];const errors=[];await Promise.all(entries.map(async([ip,s])=>{try{await wled(ip,'/json/state',{...restorePayload(s),...(forceOff?{on:false}:{})});snapshots.delete(ip);}catch(e){errors.push(`${ip}: ${e.message}`);}}));if(errors.length)status.error='Could not restore some tubes. Retry Stop, or open WLED. '+errors.join('; ');}
async function stop(forceOff=false){
 if(status.busy)throw Error('A tube action is in progress. Try again in a moment.');
 status.live=false;status.busy=true;status.error='';
 for(const t of config.tubes)sendFrame(t,Buffer.alloc(t.count*3));
 await restoreAll(forceOff);
 if(forceOff){const failures=[];await Promise.all(config.tubes.filter(t=>t.ip&&t.enabled).map(async t=>{try{await wled(t.ip,'/json/state',{on:false,live:false,udpn:{nn:true}});}catch(e){failures.push(t.name);}}));if(failures.length)status.error='Blackout could not reach: '+failures.join(', ')+'.';}
 status.busy=false;sessionOwner='';
}
async function start(owner){
 if(restarting)throw Error('TubeRoom is restarting for an update.');
 if(status.busy||identifying)throw Error('Wait for the current tube action to finish.');
 if(status.live){if(sessionOwner!==owner)throw Error('Another tab is controlling the tubes. Stop it first.');return;}
 if(snapshots.size)throw Error('A previous tube state still needs restoring. Click Stop and retry.');
 const active=config.tubes.filter(t=>t.ip&&t.enabled);if(!active.length)throw Error('Connect at least one tube in Setup first.');
 if(status.source==='none'&&config.effect!=='solid')throw Error('Start your microphone, play a music file, or select Demo first.');
 if(status.source==='mic'&&Date.now()-lastAudio>1800)throw Error('Microphone data has stopped. Restart the microphone.');
 status.busy=true;status.error='';
 try{
  const checks=await Promise.all(active.map(probe));if(checks.some(d=>!d.ok))throw Error('A tube is unreachable. Open Setup to reconnect it or disable its slot.');if(checks.some((d,i)=>d.count!==active[i].count))throw Error('A tube’s pixel count changed. Open Setup → Check & save before starting.');
  for(const t of active){const s=await wled(t.ip,'/json/state');snapshots.set(t.ip,s);await wled(t.ip,'/json/state',{on:true,bri:255,lor:0,transition:0,seg:s.seg?.map(seg=>({id:seg.id,fx:0,col:[[0,0,0],[0,0,0],[0,0,0]]})),udpn:{send:false,rgrp:0,nn:true}});}
  status.live=true;sessionOwner=owner;lastHeartbeat=Date.now();
 }catch(e){await restoreAll();throw e;}finally{status.busy=false;}
}
function networks(){const out=[];let interfaces={};try{interfaces=os.networkInterfaces();}catch{}for(const [name,entries]of Object.entries(interfaces))for(const e of entries||[])if(e.family==='IPv4'&&!e.internal&&privateIP(e.address))out.push({name,ip:e.address,prefix:e.address.split('.').slice(0,3).join('.')});return out;}
async function scan(prefix){if(!privateIP(prefix+'.1'))throw Error('Use a local network such as 192.168.1.');const found=[];let n=1;await Promise.all(Array.from({length:24},async()=>{while(n<255){const ip=prefix+'.'+n++;try{const info=await wled(ip,'/json/info',undefined,450);if(infoValid(info))found.push({ip,name:String(info.name||'WLED'),count:info.leds.count,version:info.ver});}catch{}}}));return found.sort((a,b)=>+a.ip.split('.')[3]-+b.ip.split('.')[3]);}
let scanning=false;
function state(){return {config,status,effects,networks:networks(),version:VERSION,pid:process.pid};}
function reply(res,code,data){res.writeHead(code,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify(data));}
async function body(req,limit=64000){let s='';for await(const chunk of req){s+=chunk;if(Buffer.byteLength(s)>limit)throw Error('Request too large');}return s?JSON.parse(s):{};}
const server=http.createServer(async(req,res)=>{
 const expectedHosts=[`127.0.0.1:${PORT}`,`localhost:${PORT}`];
 if(!expectedHosts.includes(req.headers.host)){reply(res,403,{error:'Local access only.'});return;}
 if(req.headers.origin&&!expectedHosts.some(h=>req.headers.origin===`http://${h}`)){reply(res,403,{error:'Cross-origin access is disabled.'});return;}
 const url=new URL(req.url,`http://127.0.0.1:${PORT}`);
 try{
  if(req.method==='GET'&&url.pathname==='/api/state'){reply(res,200,{...state(),token});return;}
  if(req.method==='GET'&&url.pathname==='/api/events'){
   res.writeHead(200,{'Content-Type':'text/event-stream','Cache-Control':'no-cache','Connection':'keep-alive'});res.write(': connected\n\n');clients.add(res);req.on('close',()=>clients.delete(res));return;
  }
  if(req.method==='POST'&&url.pathname.startsWith('/api/')){
   if(req.headers['x-tuberoom-token']!==token)throw Error('Refresh this page to reconnect securely.');
   const b=await body(req,url.pathname==='/api/update/install'?LIMIT+1024:64000),owner=String(req.headers['x-tuberoom-client']||'');
   if(!owner)throw Error('Missing browser session. Refresh the page.');
   if(['/api/config','/api/audio','/api/source'].includes(url.pathname)&&status.live&&sessionOwner!==owner)throw Error('Another tab is controlling the tubes.');
   if(restarting)throw Error('TubeRoom is restarting. Please wait.');
   if(['/api/update/install','/api/update/rollback'].includes(url.pathname)){
    if(process.env.TUBEROOM_MANAGED!=='1')throw Error('Reopen TubeRoom using Start-TubeRoom.command to enable automatic updates.');
    if(status.live||status.busy||identifying||snapshots.size)throw Error('Stop the lights and finish restoring the tubes before updating.');
   }
   switch(url.pathname){
    case '/api/update/status':reply(res,200,updaterInfo(DATA,VERSION));break;
    case '/api/update/source':setSource(DATA,String(b.url||''));pendingUpdate=null;reply(res,200,updaterInfo(DATA,VERSION));break;
    case '/api/update/check':{const result=await fetchUpdate(DATA,VERSION);pendingUpdate=result.available?result.bundle:null;reply(res,200,{available:result.available,version:result.version,notes:result.notes});break;}
    case '/api/update/install':{const bundle=b.bundle||pendingUpdate;if(!bundle)throw Error('Check for an update or choose an update file first.');const result=installBundle(DATA,bundle,VERSION);restarting=true;pendingUpdate=null;reply(res,200,{...result,restarting:true});setTimeout(()=>shutdown(75),200);break;}
    case '/api/update/rollback':{rollback(DATA);restarting=true;reply(res,200,{restarting:true});setTimeout(()=>shutdown(75),200);break;}

    case '/api/config':{if((status.live||status.busy||identifying)&&b.tubes)throw Error('Stop the show before editing tube connections or layout.');const c=cleanConfig(b,config);validateTubes(c);config=c;save();reply(res,200,{config});break;}
    case '/api/audio':{input={level:clamp(b.level),bass:clamp(b.bass),mid:clamp(b.mid),high:clamp(b.high),beat:!!b.beat||input.beat};lastAudio=Date.now();reply(res,200,{ok:true});break;}
    case '/api/source':{if(!['mic','file','demo','none'].includes(b.source))throw Error('Unknown audio input.');status.source=b.source;input={level:0,bass:0,mid:0,high:0,beat:false};lastAudio=0;reply(res,200,{ok:true});break;}
    case '/api/heartbeat':{if(owner===sessionOwner)lastHeartbeat=Date.now();reply(res,200,{ok:true});break;}
    case '/api/start':await start(owner);reply(res,200,{status});break;
    case '/api/disconnect':if(status.live&&owner===sessionOwner)await stop(true);reply(res,200,{ok:true});break;
    case '/api/stop':await stop(false);reply(res,200,{status});break;
    case '/api/blackout':await stop(true);reply(res,200,{status});break;
    case '/api/probe':{const result=await Promise.all(config.tubes.filter(t=>t.ip).map(probe));reply(res,200,{devices:result,status});break;}
    case '/api/scan':{if(scanning)throw Error('A discovery scan is already running.');scanning=true;try{reply(res,200,{found:await scan(String(b.prefix||''))});}finally{scanning=false;}break;}
    case '/api/identify':{if(status.live||status.busy||identifying)throw Error('Stop the show before identifying a tube.');const t=config.tubes[Number(b.id)];if(!t?.ip)throw Error('Set this tube’s IP first.');identifying=true;let snap;try{snap=await wled(t.ip,'/json/state');await wled(t.ip,'/json/state',{on:true,bri:255,lor:0,transition:0,seg:snap.seg?.map(seg=>({id:seg.id,fx:0,col:[[0,0,0],[0,0,0],[0,0,0]]})),udpn:{send:false,rgrp:0,nn:true}});const frame=Buffer.alloc(t.count*3);for(let i=0;i<t.count;i++){frame[i*3]=42;frame[i*3+1]=60;frame[i*3+2]=15;}for(let i=0;i<15;i++){sendFrame({...t,enabled:true},frame);await new Promise(r=>setTimeout(r,50));}reply(res,200,{ok:true});}finally{if(snap)await wled(t.ip,'/json/state',restorePayload(snap)).catch(e=>{status.error='Identify restore failed: '+e.message;});identifying=false;}break;}
    default:reply(res,404,{error:'Unknown action'});
   }return;
  }
  if(req.method!=='GET'){reply(res,405,{error:'Method not allowed'});return;}
  const files={'/':'index.html','/app.js':'app.js','/style.css':'style.css'};const file=files[url.pathname];if(!file){reply(res,404,{error:'Not found'});return;}
  res.writeHead(200,{'Content-Type':file.endsWith('.css')?'text/css':file.endsWith('.js')?'text/javascript':'text/html','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; media-src 'self' blob:; connect-src 'self'; img-src 'self' data:; frame-ancestors 'none'"});fs.createReadStream(path.join(ROOT,'public',file)).pipe(res);
 }catch(e){if(!res.headersSent)reply(res,400,{error:e.message});else res.end();}
});
const timer=setInterval(()=>{
 const now=Date.now(),t=performance.now()/1000;
 if(status.live&&!status.busy&&now-lastHeartbeat>4000){void stop(true).then(()=>{if(!status.error)status.error='Browser disconnected. Output stopped and tubes switched off.';}).catch(e=>{status.error=e.message;});}
 let a={...input};
 if(status.source==='demo'){const phase=t*2.1%1;a={bass:Math.exp(-phase*7)*.85,mid:(Math.sin(t*3)+1)*.23,high:(Math.sin(t*7)+1)*.14,level:.32+Math.exp(-phase*6)*.35,beat:phase<.08};}
 if(status.source==='none'||(['mic','file'].includes(status.source)&&now-lastAudio>650))a={bass:0,mid:0,high:0,level:0,beat:false};
 input.beat=false;status.audioAge=lastAudio?now-lastAudio:null;
 const frame=engine.render(config,a,t);seq=(seq%15)+1;
 if(status.live)frame.frames.forEach((pixels,i)=>sendFrame(config.tubes[i],pixels));
 if(tick++%2===0){const message='data: '+JSON.stringify({frames:frame.frames.map(f=>Buffer.from(f).toString('base64')),audio:frame.audio,effect:frame.effect,status})+'\n\n';for(const client of clients){if(client.writableLength>150000){client.destroy();clients.delete(client);}else client.write(message);}}
},1000/30);
server.on('error',e=>{console.error(e.code==='EADDRINUSE'?`Port ${PORT} is already in use. Open http://127.0.0.1:${PORT}`:e.message);process.exit(1);});
server.listen(PORT,HOST,()=>console.log(`TubeRoom is ready: http://${HOST}:${PORT}\nKeep this window open. Press Control-C to stop.`));
let shutting=false;async function shutdown(code=0){if(shutting)return;shutting=true;clearInterval(timer);clearTimeout(saveTimer);try{fs.writeFileSync(path.join(DATA,'settings.tmp'),JSON.stringify(config,null,2));fs.renameSync(path.join(DATA,'settings.tmp'),path.join(DATA,'settings.json'));}catch{}if(!status.busy&&(status.live||snapshots.size))await stop(false);for(const c of clients)c.end();server.close();udp.close();process.exit(code);}
process.on('SIGINT',()=>shutdown());process.on('SIGTERM',()=>shutdown());

export const clamp=(v,lo=0,hi=1)=>Math.max(lo,Math.min(hi,Number(v)||0));
export const effects=[
 {id:'velvet',name:'Velvet pulse',tag:'FULL TUBE',description:'All five tubes breathe together with the bass. Smooth, full-length light.'},
 {id:'shock',name:'Shockwave',tag:'SPATIAL',description:'Each detected beat sends a ring of light through your room layout.'},
 {id:'sweep',name:'Liquid sweep',tag:'SPATIAL',description:'Wide curtains of color flow across the room, pushed by the music.'},
 {id:'chase',name:'Beat relay',tag:'RHYTHMIC',description:'Each bass hit hands the light to the next tube. Soft trailing glow.'},
 {id:'orbit',name:'Orbit',tag:'SPATIAL',description:'A rotating beam cuts through the layout; bass widens the beam.'},
 {id:'prism',name:'Prism melt',tag:'IMMERSIVE',description:'A continuous two-color field, bending with bass, mids and treble.'},
 {id:'ember',name:'Afterglow',tag:'ATMOSPHERIC',description:'Warm, flowing variation with music-driven brightness. No level bars.'},
 {id:'solid',name:'Color wash',tag:'STEADY',description:'Your chosen color across every pixel. Works without a microphone.'}
];
export function defaults(){return {version:1,brightness:.3,gain:1.5,gate:.009,speed:1,softness:.65,effect:'velvet',auto:false,colorA:'#bbff5e',colorB:'#704bff',tubes:Array.from({length:5},(_,i)=>({id:i,name:`Tube ${i+1}`,ip:'',count:100,x:180+i*160,y:300,angle:0,length:230,reverse:false,enabled:true}))};}
export function cleanConfig(input,base=defaults()){
 const c={...base};
 for(const [key,lo,hi] of [['brightness',0,1],['gain',.2,8],['gate',.001,.08],['speed',.2,3],['softness',0,1]]) if(key in input)c[key]=clamp(input[key],lo,hi);
 if(effects.some(e=>e.id===input.effect))c.effect=input.effect;
 if(typeof input.auto==='boolean')c.auto=input.auto;
 for(const key of ['colorA','colorB'])if(/^#[\da-f]{6}$/i.test(input[key]))c[key]=input[key];
 if(input.tubes){if(!Array.isArray(input.tubes)||input.tubes.length!==5)throw Error('Exactly five tube slots are required.');c.tubes=input.tubes.map((t,i)=>({id:i,name:String(t.name||`Tube ${i+1}`).slice(0,30),ip:String(t.ip||'').trim(),count:Math.round(clamp(t.count,1,1500)),x:clamp(t.x,45,955),y:clamp(t.y,45,555),angle:clamp(t.angle,-180,180),length:clamp(t.length,50,420),reverse:!!t.reverse,enabled:t.enabled!==false}));}
 return c;
}
const rgb=s=>[1,3,5].map(i=>parseInt(s.slice(i,i+2),16));
const mix=(a,b,t)=>a.map((x,i)=>x+(b[i]-x)*clamp(t));
export function point(tube,j){const u=(tube.count===1?0:j/(tube.count-1)-.5)*tube.length,r=tube.angle*Math.PI/180;return {x:tube.x+Math.sin(r)*u,y:tube.y+Math.cos(r)*u};}
export class Engine{
 constructor(){this.a={bass:0,mid:0,high:0,level:0,beat:false};this.lastBeat=-10;this.beats=0;this.rings=[];this.pulse=0;this.phase=0;this.prev=0;this.autoIndex=0;}
 render(c,input,t){
  const dt=clamp(t-this.prev,0,.1);this.prev=t;const decay=Math.exp(-dt/(.08+c.softness*.28));
  for(const k of ['bass','mid','high','level'])this.a[k]=Math.max(clamp(input[k]),this.a[k]*decay);
  this.pulse*=Math.exp(-dt/(.1+c.softness*.4));
  if(input.beat&&t-this.lastBeat>.18){this.lastBeat=t;this.beats++;this.pulse=1;this.rings.push({t,x:500+Math.sin(this.beats*2.4)*180,y:300+Math.cos(this.beats*1.7)*80});if(this.beats%32===0)this.autoIndex++;}
  this.rings=this.rings.filter(r=>t-r.t<3);this.phase+=dt*c.speed*(.5+this.a.bass*.9);
  const a=rgb(c.colorA),b=rgb(c.colorB),audio=this.a,phase=this.phase;
  const effect=c.auto?['velvet','sweep','shock','prism','chase','orbit','ember'][this.autoIndex%7]:c.effect;
  const frames=c.tubes.map((tube,ti)=>{
   const pixels=new Uint8Array(tube.count*3);
   for(let j=0;j<tube.count;j++){
    const p=point(tube,j),x=p.x/1000,y=p.y/600,u=tube.count===1?.5:j/(tube.count-1);let intensity=0,blend=0;
    const energy=clamp(audio.level*.6+audio.bass*.65);
    if(effect==='velvet'){intensity=.035+energy*.7+this.pulse*.25;blend=audio.high*.5;}
    if(effect==='shock'){intensity=energy*.08;for(const ring of this.rings){const age=t-ring.t,dist=Math.hypot(p.x-ring.x,p.y-ring.y);intensity+=Math.exp(-(((dist-age*370*c.speed)/75)**2))*Math.exp(-age*.6);}blend=clamp(Math.hypot(x-.5,y-.5));}
    if(effect==='sweep'){const wave=(1+Math.sin(x*8+y*2-phase*3))/2;intensity=(.08+energy*.92)*(.12+.88*wave**2);blend=wave;}
    if(effect==='chase'){const d=(ti-(this.beats%5)+5)%5;intensity=(d===0?.2+energy*.5+this.pulse*.3:.04+energy*.1)*Math.exp(-d*.5);blend=d/4;}
    if(effect==='orbit'){const theta=phase*1.7,dist=Math.abs((x-.5)*Math.cos(theta)+(y-.5)*.6*Math.sin(theta));intensity=(.1+energy*.9)*Math.exp(-((dist/(.035+audio.bass*.16))**2));blend=(1+Math.sin(phase+y*4))/2;}
    if(effect==='prism'){blend=(Math.sin(x*7+Math.sin(y*5+phase)+phase*.7+audio.mid)+1)/2;intensity=(.07+energy*.8+audio.high*.13)*(.65+.35*Math.sin(u*5+phase)**2);}
    if(effect==='ember'){const noise=(Math.sin(x*17+phase)+Math.sin(y*13-phase*.7)+Math.sin(u*19+phase*1.6)+3)/6;intensity=(.03+energy*.95)*(.3+.7*noise);blend=noise*.8;}
    if(effect==='solid'){intensity=1;blend=0;}
    const color=mix(a,b,blend),at=(tube.reverse?tube.count-1-j:j)*3;
    for(let k=0;k<3;k++)pixels[at+k]=Math.round(clamp(intensity)*color[k]*c.brightness*(tube.enabled?1:0));
   }
   return pixels;
  });return {frames,effect,audio:{...audio,pulse:this.pulse,beats:this.beats}};
 }
}
export function ddpPackets(bytes,seq=1){
 const packets=[];for(let offset=0;offset<bytes.length;offset+=1440){const data=bytes.subarray(offset,offset+1440),header=Buffer.alloc(10);header[0]=0x40|(offset+data.length===bytes.length?1:0);header[1]=seq&15;header[2]=1;header[3]=1;header.writeUInt32BE(offset,4);header.writeUInt16BE(data.length,8);packets.push(Buffer.concat([header,data]));}return packets;
}

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {spawnSync} from 'node:child_process';
export const FORMAT='tuberoom-update-v1';
export const FILES=['package.json','server.mjs','engine.mjs','updater.mjs','public/index.html','public/app.js','public/style.css'];
export const LIMIT=2*1024*1024;
const hash=s=>crypto.createHash('sha256').update(s).digest('hex');
