 if(audioBusy||!analyser)return;analyser.getByteFrequencyData(freq);analyser.getFloatTimeDomainData(timeData);let sum=0;for(const v of timeData)sum+=v*v;const rms=Math.sqrt(sum/timeData.length),gate=config.gate;peak=Math.max(rms,peak*.994,.035);const level=clamp((rms-gate)/(Math.max(.03,peak*.9))*config.gain*.65);const band=(low,high)=>{const lo=Math.max(1,Math.floor(low*analyser.fftSize/audioContext.sampleRate)),hi=Math.min(freq.length,Math.ceil(high*analyser.fftSize/audioContext.sampleRate));let p=0;for(let i=lo;i<hi;i++)p+=(freq[i]/255)**2;return Math.sqrt(p/Math.max(1,hi-lo));};const rawBass=band(35,220),rawMid=band(220,2500),rawHigh=band(2500,11000),now=performance.now();beatAverage=beatAverage*.965+rawBass*.035;const beat=rms>gate&&rawBass>Math.max(.12,beatAverage*1.16)&&rawBass-previousBass>.012&&now-lastBeatAt>220;if(beat)lastBeatAt=now;previousBass=rawBass;
 const active=rms>gate?clamp((rms-gate)/Math.max(gate,.005)):0;
 audioBusy=true;try{await api('audio',{level,bass:clamp(rawBass*config.gain*active),mid:clamp(rawMid*config.gain*active),high:clamp(rawHigh*config.gain*active),beat});}catch(e){notice(e.message);}finally{audioBusy=false;}
 },1000/30);}
$('mic').onclick=run(enableMic);$('micStep').onclick=run(enableMic);$('audioDevice').onchange=run(async()=>{if(source==='mic'){source='none';await enableMic();}});
$('demo').onclick=run(async()=>{const next=source==='demo'?'none':'demo';stopAudio();await api('source',{source:next});source=next;$('player').hidden=true;setText('audioHelp',next==='demo'?'Simulated 126 BPM input. Switch to microphone for real music.':'Enable your microphone to react to music.');});
$('loadMusic').onclick=()=>$('musicFile').click();$('musicFile').onchange=run(async e=>{const file=e.target.files[0];if(!file)return;stopAudio();await audioBase();await api('source',{source:'none'});source='none';if(fileURL)URL.revokeObjectURL(fileURL);fileURL=URL.createObjectURL(file);$('player').src=fileURL;$('player').hidden=false;if(!fileNode)fileNode=audioContext.createMediaElementSource($('player'));fileNode.connect(analyser);fileNode.connect(audioContext.destination);try{await $('player').play();await api('source',{source:'file'});source='file';startAudioLoop();setText('audioHelp','Analyzing this file directly: '+file.name);}catch(e){stopAudio();throw Error('This music file could not play. Try an MP3, WAV or M4A file.');}});
function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('export').onclick=run(async()=>{if(layoutDirty)await saveLayout();await flush();download('TubeRoom-setup.json',JSON.stringify(config,null,2));});$('import').onclick=()=>{if(status.live){notice('Stop the lights before importing a setup.');return;}$('importFile').click();};$('importFile').onchange=run(async e=>{const f=e.target.files[0];if(!f)return;if(f.size>64000)throw Error('Setup file is too large.');const incoming=JSON.parse(await f.text());await flush();config=(await api('config',incoming)).config;layoutDirty=false;populate();cards();selection();notice('Setup imported. Check tube connections before starting.');});

let updateBundle=null,updateBusy=false,installedPid=0;
function updateButtons(busy){updateBusy=busy;for(const id of ['checkUpdates','installUpdate','chooseUpdate','saveUpdateSource','rollbackUpdate'])$(id).disabled=busy;}
$('updatesBtn').onclick=run(async()=>{$('updates').showModal();const u=await api('update/status');setText('updateVersion','Installed: TubeRoom '+u.version);$('updateSource').value=u.source;$('rollbackUpdate').hidden=!u.canRollback;$('installUpdate').hidden=true;updateBundle=null;setText('updateNotes','');setText('updateMessage',u.notice||(!u.managed?'Reopen with Start-TubeRoom.command to enable updates.':u.source?'Ready to check for updates.':'Online publishing is not connected yet. You can install an update file here.'));});
$('saveUpdateSource').onclick=run(async()=>{await api('update/source',{url:$('updateSource').value.trim()});updateBundle=null;$('installUpdate').hidden=true;setText('updateMessage','Update source saved. Click Check for updates.');});
$('checkUpdates').onclick=run(async()=>{updateButtons(true);setText('updateMessage','Checking for updates…');try{const u=await api('update/check');updateBundle=null;$('installUpdate').hidden=!u.available;setText('updateMessage',u.available?'TubeRoom '+u.version+' is ready to install.':'You already have the latest version from this source.');setText('updateNotes',u.notes||'');}finally{updateButtons(false);}});
$('chooseUpdate').onclick=()=>{if(!updateBusy)$('updateFile').click();};
$('updateFile').onchange=run(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('This update file is too large.');const b=JSON.parse(await file.text());if(b.format!=='tuberoom-update-v1'||!b.version||!Array.isArray(b.files))throw Error('Choose a .tuberoom-update.json file, not the app ZIP or a settings export.');updateBundle=b;$('installUpdate').hidden=false;setText('updateMessage','Ready to install TubeRoom '+b.version+'.');setText('updateNotes',String(b.notes||''));e.target.value='';});
async function waitForRestart(){stopAudio();source='none';eventStream?.close();setText('updateMessage','Restarting TubeRoom… Your settings are saved.');for(let i=0;i<60;i++){await new Promise(r=>setTimeout(r,500));try{const r=await fetch('/api/state');const s=await r.json();if(s.pid&&s.pid!==installedPid){window.location.reload();return;}}catch{}}throw Error('Restart is taking longer than expected. Close the Terminal window, reopen Start-TubeRoom.command, then refresh Safari.');}
async function installOrRollback(route,data){if(status.live)throw Error('Stop the lights before updating.');await flush();if(layoutDirty)await saveLayout();updateButtons(true);try{const current=await(await fetch('/api/state')).json();installedPid=current.pid;await api(route,data);await waitForRestart();}finally{updateButtons(false);}}
$('installUpdate').onclick=run(()=>installOrRollback('update/install',updateBundle?{bundle:updateBundle}:{}));
$('rollbackUpdate').onclick=run(()=>installOrRollback('update/rollback',{}));

async function boot(){
 const response=await fetch('/api/state');const s=await response.json();token=s.token;config=s.config;effects=s.effects;renderEffects();populate();updateStatus(s.status);config.tubes.forEach(t=>$('selectedTube').add(new Option(t.name,t.id)));for(const n of s.networks)$('network').add(new Option(`${n.name} · ${n.ip}`,n.prefix));$('prefix').value=s.networks[0]?.prefix||'192.168.1';if(!s.networks.length)$('network').add(new Option('Enter router subnet',''));selection();draw();await devices().catch(()=>{});
 eventStream=new EventSource('/api/events');eventStream.onmessage=e=>{const data=JSON.parse(e.data);lastFrame=Date.now();bridge=true;frames=data.frames.map(s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0)));audio=data.audio;updateStatus(data.status);for(const [key,id]of [['bass','bassMeter'],['mid','midMeter'],['high','highMeter']])$(id).style.width=clamp(audio[key])*100+'%';setText('currentEffect',effects.find(f=>f.id===data.effect)?.name||data.effect);setText('beatText',source==='none'?'Waiting for audio':`BEAT ${String(audio.beats).padStart(3,'0')}${audio.level<.015?' · quiet':''}`);};eventStream.onerror=()=>{bridge=false;cards();notice('Connection lost. Keep Start-TubeRoom.command running, then reload this page.');};
 setInterval(()=>{if(status.live)api('heartbeat').catch(()=>{});if(lastFrame&&Date.now()-lastFrame>2500){bridge=false;cards();}if(['mic','file'].includes(source)&&status.audioAge>2000)setText('audioHelp','Audio data has stopped. Restart your input.');},1000);
 setInterval(()=>{if(status.live)api('probe').catch(()=>{});},12000);
}
